/**
 * Hono-free request dispatch for `platform: "cloudflare-worker"` when no
 * `serverEntry` is configured. Built entirely on the standard Fetch API
 * (`Request`/`Response`/`URL`/`Headers`). Two shapes, both generated by
 * `cloudflare-bundle-generator.ts`:
 *
 * - `emitCloudflareContextHelper` + `emitCloudflareDispatch`: the full RPC
 *   dispatch route, used by every independent per-function Worker (each one
 *   is a fully self-contained Worker, reachable directly). No shared
 *   framework baseline duplicated across independent deployments — just
 *   this glue plus the handler code that Worker actually owns.
 * - `emitCloudflareGatewayDispatch`: a much thinner route used by the
 *   combined Worker, which forwards each endpoint to the independent Worker
 *   that implements it via a Service Binding, instead of running handler
 *   code itself. See {@link https://developers.cloudflare.com/workers/runtime-apis/bindings/service-bindings/}.
 *
 * `__serverContext` mirrors `dev-server/middleware.ts`'s `createServerContext`
 * (the same lightweight fallback already used in dev without `serverEntry`),
 * extended with `env`/`executionCtx` so HTTP-method handlers can still read
 * Cloudflare bindings and secrets via `c.env`, matching what the Hono-backed
 * paths (platform: "hono", and cloudflare-worker with `serverEntry`) already
 * expose at runtime.
 *
 * When `serverEntry` *is* configured, generated endpoints are instead
 * mounted onto the user's own Hono app (see `handler-emitter.ts`'s
 * `emitApiDispatchRoute`) — that's an explicit choice the user makes by
 * exporting a Hono-compatible app, not something this plugin's own codegen
 * imposes.
 */

export function emitCloudflareContextHelper(): string[] {
  return [
    "function __serverContext(raw, env, executionCtx) {",
    "  const url = new URL(raw.url);",
    "  return {",
    "    req: {",
    "      raw,",
    "      url: raw.url,",
    "      method: raw.method,",
    "      param(key) {",
    "        if (key === undefined) return {};",
    "        return undefined;",
    "      },",
    "      query(key) {",
    "        if (key === undefined) return Object.fromEntries(url.searchParams);",
    "        return url.searchParams.get(key) ?? undefined;",
    "      },",
    "      header(name) {",
    "        if (name === undefined) {",
    "          const headers = {};",
    "          raw.headers.forEach((v, k) => { headers[k] = v; });",
    "          return headers;",
    "        }",
    "        return raw.headers.get(name) ?? undefined;",
    "      },",
    "      json: () => raw.json(),",
    "      text: () => raw.text(),",
    "    },",
    "    env,",
    "    executionCtx,",
    "  };",
    "}",
    "",
    "function __jsonResponse(data, status, headers) {",
    "  return new Response(JSON.stringify(data), {",
    "    status: status || 200,",
    "    headers: { \"Content-Type\": \"application/json\", ...(headers || {}) },",
    "  });",
    "}",
    "",
  ];
}

/**
 * Builds `__dispatch(request, env, executionCtx)` — the RPC handler for
 * `/{pathnameBase}/*` — and the `export default { fetch }` Module Worker
 * export. Same request/response contract as the Hono dispatch route
 * (methods, JSON body handling, status codes), written directly against
 * `Request`/`Response` instead of a Hono `Context`.
 *
 * Requires `__serverHandlers` (see `emitServerHandlersMap`) and
 * `__serverContext`/`__jsonResponse` (see `emitCloudflareContextHelper`) to
 * already be defined earlier in the module.
 */
export function emitCloudflareDispatch(apiPrefix: string): string[] {
  return [
    "async function __dispatch(request, env, executionCtx) {",
    "  const url = new URL(request.url);",
    `  if (!url.pathname.startsWith(${JSON.stringify(apiPrefix)})) {`,
    '    return new Response("Not Found", { status: 404 });',
    "  }",
    "",
    "  let endpoint;",
    "  try {",
    `    endpoint = decodeURIComponent(url.pathname.slice(${apiPrefix.length}));`,
    "  } catch {",
    '    return __jsonResponse({ error: "Bad request" }, 400);',
    "  }",
    "  const entry = __serverHandlers[endpoint];",
    "",
    "  if (!entry) {",
    "    return __jsonResponse({ error: `Handler not found for endpoint: ${endpoint}` }, 404);",
    "  }",
    "",
    '  const expectedMethod = entry.method || "POST";',
    "  if (request.method !== expectedMethod) {",
    '    return __jsonResponse({ error: "Method not allowed" }, 405, { Allow: expectedMethod });',
    "  }",
    "",
    "  try {",
    "    let result;",
    "    if (entry.method) {",
    "      result = await entry.fn(__serverContext(request, env, executionCtx));",
    "    } else {",
    '      const contentType = request.headers.get("content-type");',
    '      const contentMime = contentType?.split(";", 1)[0]?.trim().toLowerCase();',
    '      if (contentMime && contentMime !== "application/json" && !contentMime.endsWith("+json")) {',
    '        return __jsonResponse({ error: "Unsupported media type. Expected application/json" }, 415);',
    "      }",
    "      let payload;",
    "      try {",
    "        const rawBody = await request.text();",
    "        const trimmedBody = rawBody.trim();",
    "        payload = trimmedBody.length > 0 ? JSON.parse(trimmedBody) : [];",
    "      } catch {",
    '        return __jsonResponse({ error: "Invalid JSON payload" }, 400);',
    "      }",
    "      const args = Array.isArray(payload) ? payload : [payload];",
    "      result = await entry.fn(...args);",
    "    }",
    "    if (result instanceof Response) return result;",
    "    if (result === undefined) return new Response(null, { status: 204 });",
    "    return __jsonResponse(result);",
    "  } catch (e) {",
    "    const message = e instanceof Error ? e.message : String(e);",
    "    console.error(`[server-build] Error in ${endpoint}:`, e);",
    "    return __jsonResponse({ error: message }, 500);",
    "  }",
    "}",
    "",
    "export default {",
    "  fetch(request, env, executionCtx) {",
    "    return __dispatch(request, env, executionCtx);",
    "  },",
    "};",
    "",
  ];
}

export interface CloudflareGatewayRoute {
  /** Endpoints implemented by the independent Worker this binding points at. */
  endpoints: string[];
  /** Service Binding name, e.g. `"SVC_TODOS_GET_TODOS"` (see `wrangler-config.ts`'s `serviceBindingName`). */
  binding: string;
}

/**
 * Builds the gateway's `__dispatch(request, env)` — looks up which
 * independent Worker owns the requested endpoint and forwards the request
 * to it via `env[binding].fetch(request)`, returning its response as-is.
 * Runs no handler code and needs no imports: the target Worker owns the
 * full RPC contract (methods, JSON body handling, status codes) for its own
 * endpoints, exactly as it would if reached directly over the public
 * internet instead of through this gateway.
 */
export function emitCloudflareGatewayDispatch(
  apiPrefix: string,
  routes: CloudflareGatewayRoute[],
): string[] {
  const routeEntries: string[] = [];
  for (const route of routes) {
    for (const endpoint of route.endpoints) {
      routeEntries.push(`  ${JSON.stringify(endpoint)}: ${JSON.stringify(route.binding)},`);
    }
  }

  return [
    "// Maps each endpoint to the Service Binding for the independent Worker",
    "// that implements it (see dist/server/functions/<name>/).",
    "const __routes = {",
    ...routeEntries,
    "};",
    "",
    "async function __dispatch(request, env) {",
    "  const url = new URL(request.url);",
    `  if (!url.pathname.startsWith(${JSON.stringify(apiPrefix)})) {`,
    '    return new Response("Not Found", { status: 404 });',
    "  }",
    "",
    "  let endpoint;",
    "  try {",
    `    endpoint = decodeURIComponent(url.pathname.slice(${apiPrefix.length}));`,
    "  } catch {",
    '    return new Response(JSON.stringify({ error: "Bad request" }), { status: 400, headers: { "Content-Type": "application/json" } });',
    "  }",
    "",
    "  const binding = __routes[endpoint];",
    "  const service = binding ? env[binding] : undefined;",
    "  if (!service) {",
    "    return new Response(JSON.stringify({ error: `Handler not found for endpoint: ${endpoint}` }), { status: 404, headers: { \"Content-Type\": \"application/json\" } });",
    "  }",
    "",
    "  try {",
    "    // Forwards on the same server with no added network latency; the",
    "    // target Worker's own fetch handler runs exactly as it would for a",
    "    // direct public request.",
    "    return await service.fetch(request);",
    "  } catch (e) {",
    "    const message = e instanceof Error ? e.message : String(e);",
    "    return new Response(",
    "      JSON.stringify({ error: `Upstream Worker for '${endpoint}' is unavailable: ${message}` }),",
    '      { status: 502, headers: { "Content-Type": "application/json" } },',
    "    );",
    "  }",
    "}",
    "",
    "export default {",
    "  fetch(request, env) {",
    "    return __dispatch(request, env);",
    "  },",
    "};",
    "",
  ];
}
